    #[derive(Clone, Copy)]
    pub struct CiiCtrlReadVal(u32);
    impl CiiCtrlReadVal {
        /// CII Ctrl reset
        ///
        /// Reset CII controller.
        #[inline(always)]
        pub fn cii_rst(&self) -> bool {
            ((self.0 >> 31) & 1) != 0
        }
        /// CII Update LUT_CFG_BF.VALUE enable
        ///
        /// LUT_CFG_BF.VALUE upate enable. Regardless of CII_CTRL_EN, LUT_CFG_BF is updated when CII_LUT_UPT_EN = 1.
        #[inline(always)]
        pub fn cii_lut_upd_en(&self) -> bool {
            ((self.0 >> 5) & 1) != 0
        }
        /// CII Full F/W control
        ///
        /// Full F/W control.
        /// 0: CiiCtrl handles TDISP rules on configuration write. H/W determine the operation based on LUT_CFG and LUT_CFG_BF.
        /// 1: CiiCtrl detects all the configuration write without checking LUT_CFG, halt the CfgWr, and interrupt F/W. F/W should handle TDISP rule checking, TDISP_ST update, and overriding.
        #[inline(always)]
        pub fn cii_full_fw_ctrl(&self) -> bool {
            ((self.0 >> 4) & 1) != 0
        }
        /// CII control enable
        ///
        /// 0: CIICtrl is disabled.
        /// 1: CIICtrl is enabled.
        #[inline(always)]
        pub fn cii_ctrl_en(&self) -> bool {
            ((self.0 >> 0) & 1) != 0
        }
        /// Construct a WriteVal that can be used to modify the contents of this register value.
        pub fn modify(self) -> CiiCtrlWriteVal {
            CiiCtrlWriteVal(self.0)
        }
    }
    impl From<u32> for CiiCtrlReadVal {
        fn from(val: u32) -> Self {
            Self(val)
        }
    }
    impl From<CiiCtrlReadVal> for u32 {
        fn from(val: CiiCtrlReadVal) -> u32 {
            val.0
        }
    }
