    #[derive(Clone, Copy)]
    pub struct CiiStatusReadVal(u32);
    impl CiiStatusReadVal {
        /// CII FSM
        ///
        /// CII internal signals
        /// [9:9] Found LUT_CFG_BF entries                                    (1'b1: Found)
        /// [8:8] LUT_CFG_BF value match                                      (1'b1: Match)
        /// [7:7] Detect corresponding TDISP state is CONFIG_LOCKED or RUN    (1'b1: True)
        /// [6:5] LUT_CFG searching FSM
        /// [4:3] LUT_CFG_BF searching FSM
        /// [2:0] CII_CTRL main FSM
        #[inline(always)]
        pub fn cii_dbg(&self) -> u32 {
            (self.0 >> 0) & 0xffff
        }
    }
    impl From<u32> for CiiStatusReadVal {
        fn from(val: u32) -> Self {
            Self(val)
        }
    }
    impl From<CiiStatusReadVal> for u32 {
        fn from(val: CiiStatusReadVal) -> u32 {
            val.0
        }
    }
